style.css:
@-moz-document domain("roblox.com") {
.profile-page {
        background-image: url(https://i.pinimg.com/originals/39/39/a8/3939a8485b1817679fc4ea7a429b288c.jpg);
        background-size: cover;
        background-repeat: no-repeat;
        background-attachment: fixed;
        background-position: center;
    }
    
    /* Ajusta a transparência do conteúdo para melhor visibilidade */
    .container-main, .profile-header {
        background-color: rgba(255, 255, 255, 0.8);
    }
}
